INSERT INTO crm_product (id, name, no, unit, price, status, category_id, description, owner_user_id, creator, create_time, updater, update_time, tenant_id, deleted) VALUES
(100, '预制直埋保温管 DN200', 'TX-BW-200', 11, 128.00, 1, 102, '工作钢管 219×6 + 聚氨酯保温层 + HDPE 外护管；导热系数≤0.033W/(m·K)，密度≥60kg/m³，耐温 120℃，用于市政供热一二次网', 81016, '1', NOW(), '1', NOW(), 2025, b'0'),
(101, '3PE 防腐钢管 DN400×8', 'TX-FF-400', 11, 680.00, 1, 102, '环氧粉末涂层≥150μm + 胶粘剂层≥170μm + 聚乙烯层≥2.5mm，总防腐层厚度≥4.2mm，附着力与阴极剥离试验合格，用于油气长输管线', 81016, '1', NOW(), '1', NOW(), 2025, b'0'),
(102, '钢套钢蒸汽保温管 DN150', 'TX-BW-150S', 11, 420.00, 1, 102, '工作钢管 + 岩棉/硅酸铝保温层 + 外套钢管，内滑动结构，用于高温蒸汽管线（≤350℃）', 81016, '1', NOW(), '1', NOW(), 2025, b'0'),
(103, '岩棉管壳 DN57×50', 'TX-BW-YW57', 9, 220.00, 1, 100, 'A 级不燃，密度 100kg/m³，导热系数≤0.036W/(m·K)，耐温 600℃，用于中温管道保温', 81016, '1', NOW(), '1', NOW(), 2025, b'0'),
(104, '岩棉板 1200×600×50', 'TX-BW-YWB', 9, 180.00, 1, 100, 'A 级不燃岩棉板，密度 120kg/m³，导热系数≤0.040W/(m·K)，用于设备、储罐、建筑外墙保温', 81016, '1', NOW(), '1', NOW(), 2025, b'0'),
(105, '硅酸铝针刺毯 3600×610×50', 'TX-BW-GSL', 9, 850.00, 1, 100, '耐温 1000℃，密度 128kg/m³，导热系数≤0.034W/(m·K)，用于锅炉、加热炉、高温蒸汽管道隔热', 81016, '1', NOW(), '1', NOW(), 2025, b'0'),
(106, '玻璃棉管壳 DN89×50', 'TX-BW-BLM', 9, 190.00, 1, 100, 'A 级不燃，密度 64kg/m³，导热系数≤0.035W/(m·K)，用于暖通及中低温管道', 81016, '1', NOW(), '1', NOW(), 2025, b'0'),
(107, '橡塑保温管 B1 级 DN25×20', 'TX-BW-XS25', 11, 18.00, 1, 100, 'B1 级难燃，湿阻因子≥10000，导热系数≤0.034W/(m·K)，用于空调冷热水管道防结露', 81016, '1', NOW(), '1', NOW(), 2025, b'0'),
(108, '聚氨酯硬泡保温管壳 DN108×40', 'TX-BW-PU108', 9, 520.00, 1, 100, 'B1 级聚氨酯，导热系数≤0.024W/(m·K)，吸水率低，用于低温工艺管线保冷', 81016, '1', NOW(), '1', NOW(), 2025, b'0'),
(109, '气凝胶绝热毡 5mm', 'TX-BW-QNJ', 2, 1200.00, 1, 100, '耐温 650℃，导热系数≤0.021W/(m·K)，疏水率≥98%，用于深冷、高温复合绝热', 81016, '1', NOW(), '1', NOW(), 2025, b'0'),
(110, '环氧富锌底漆 20kg/桶', 'TX-FF-HXFZ', 6, 680.00, 1, 101, '锌含量≥80%，干膜厚度 60-80μm，配套中间漆/面漆，用于钢结构重防腐底漆', 81016, '1', NOW(), '1', NOW(), 2025, b'0'),
(111, '环氧云铁中间漆 25kg/桶', 'TX-FF-HYYT', 6, 520.00, 1, 101, '屏蔽性能优异，干膜厚度 100μm，与富锌底漆/聚氨酯面漆配套', 81016, '1', NOW(), '1', NOW(), 2025, b'0'),
(112, '聚氨酯面漆 20kg/桶', 'TX-FF-JAZ', 6, 980.00, 1, 101, '耐候耐盐雾，光泽保持率高，用于户外钢结构面漆', 81016, '1', NOW(), '1', NOW(), 2025, b'0'),
(113, '氟碳面漆 20kg/桶', 'TX-FF-FT', 6, 1600.00, 1, 101, '超耐候氟碳涂料，耐盐雾 2000h+，用于海洋环境、高盐雾区域钢结构', 81016, '1', NOW(), '1', NOW(), 2025, b'0'),
(114, '玻璃鳞片胶泥 25kg/桶', 'TX-FF-BLLP', 6, 350.00, 1, 101, '耐温 150℃，涂层 2mm 两道，耐酸耐腐蚀，用于储罐、污水池、烟道衬里', 81016, '1', NOW(), '1', NOW(), 2025, b'0'),
(115, '无机硅酸锌车间底漆 25kg/组', 'TX-FF-WJSG', 13, 1200.00, 1, 101, '锌粉含量≥80%，用于钢材预处理流水线车间底漆，焊接性能好', 81016, '1', NOW(), '1', NOW(), 2025, b'0'),
(116, 'HDPE 外护管 DN250×3.6', 'TX-WH-HDPE250', 11, 78.00, 1, 104, '高密度聚乙烯外护管，抗冲击耐老化，用于直埋保温管外护', 81016, '1', NOW(), '1', NOW(), 2025, b'0'),
(117, '电热熔套 DN200', 'TX-WH-DRRT', 13, 35.00, 1, 104, '电热熔焊接补口套，密封性能好，用于直埋保温管接口补口', 81016, '1', NOW(), '1', NOW(), 2025, b'0'),
(118, '热收缩带补口 300mm', 'TX-WH-RSSD', 11, 28.00, 1, 104, '辐射交联聚乙烯热收缩带，配合底胶使用，用于 3PE 防腐管补口', 81016, '1', NOW(), '1', NOW(), 2025, b'0'),
(119, '镀锌铁皮护壳 0.5mm', 'TX-WH-DXTP', 2, 22.00, 1, 104, '镀锌铁皮外护壳，用于架空管道保温层外护', 81016, '1', NOW(), '1', NOW(), 2025, b'0'),
(120, '管道防腐保温施工服务', 'TX-SV-GD', 11, 85.00, 1, 103, '包工包料：喷砂除锈 Sa2.5、涂装、保温包覆、外护安装、补口补伤，含施工方案与技术交底', 81016, '1', NOW(), '1', NOW(), 2025, b'0'),
